void main() {

  // buf reads itself = feedback, and reading it off-centre is what makes the
  // wake travel. The buffer is 8-bit: subtract less than one LSB and dim
  // pixels never reach black.
  float steps = iTimeDelta * 60.0;
  float prev = texture2D(iChannel0, uv + vec2(0.0, drift * steps)).r;
  prev = max(prev * pow(decay, steps) - 1.5 / 255.0 * steps, 0.0);

  float y = 0.5 + wave(uv.x, iTime * speed);
  float crest = smoothstep(0.012, 0.0, abs(uv.y - y));

  gl_FragColor = vec4(vec3(prev + crest * (1.0 - prev)), 1.0);
}

void main() {
  // buf carries one number per pixel; this pass is where it becomes a picture.
  // Feeding a curve back into a loop compounds it every frame, so the tone
  // curve has to live out here, after the feedback.
  float v = texture2D(iChannel0, uv).r;
  vec3 col = palette(hue + 0.28 * v) * v;
  col += vec3(1.0, 0.72, 0.42) * smoothstep(0.7, 1.0, v) * 0.5;
  gl_FragColor = vec4(tone(col, 0.04, exposure), 1.0);
}
